# Canonical full-date and year-only keys tolerate formatting, partial dates, and component-level errors.
def date_keys(r):
    import re
    s = str(r.get("birthdate", "") or "").strip()
    parts = re.findall(r"\d+", s)
    if not parts:
        return []
    year = ""
    a = b = None
    if len(parts) == 1 and len(parts[0]) == 4:
        year = parts[0]
    elif len(parts) >= 3:
        if len(parts[0]) == 4:
            year, a, b = parts[0], parts[1], parts[2]
        elif len(parts[-1]) == 4:
            year, a, b = parts[-1], parts[0], parts[1]
        else:
            year, a, b = parts[-1], parts[0], parts[1]
    elif any(len(p) == 4 for p in parts):
        year = next(p for p in parts if len(p) == 4)
    if not year:
        return []
    keys = ["dy:" + year.zfill(4)]
    if a is not None and b is not None:
        keys.append("dd:" + year.zfill(4) + "-" + str(int(a)) + "-" + str(int(b)))
    return keys


# Accent-insensitive name-token anchors tolerate compounds, omitted names, punctuation, and first/last swaps.
def name_token_keys(r):
    import re
    import unicodedata
    def norm(s):
        s = unicodedata.normalize("NFKD", str(s or "")).encode("ascii", "ignore").decode().lower()
        s = s.translate(str.maketrans({"0": "o", "1": "i", "3": "e", "4": "a", "5": "s", "7": "t", "9": "g"}))
        return re.findall(r"[a-z]+", s)
    tokens = []
    for field in ("first", "last"):
        for token in norm(r.get(field, "")):
            if len(token) >= 2 and token not in tokens:
                tokens.append(token)
    return ["nm:" + t[:20] for t in tokens[:4]]


# Identifier and location anchors use SSN suffixes, unit-stripped addresses, and compact city/zip fallbacks.
def identifier_location_keys(r):
    import re
    import unicodedata
    import hashlib
    def norm(s):
        s = unicodedata.normalize("NFKD", str(s or "")).encode("ascii", "ignore").decode().lower()
        return " ".join(re.findall(r"[a-z0-9]+", s))
    def short(tag, value):
        return tag + hashlib.blake2s(value.encode(), digest_size=6).hexdigest()
    keys = []
    ssn = re.sub(r"[^a-z0-9]", "", norm(r.get("ssn", "")))
    digits = re.sub(r"\D", "", ssn)
    if len(digits) >= 4:
        keys.append("s4:" + digits[-4:])
    elif len(ssn) >= 6:
        keys.append(short("ss:", ssn))
    address = norm(r.get("address", ""))
    if address:
        address = re.split(
            r"\b(?:apt|apartment|unit|suite|ste|block|floor|fl|room|rm|dept|area|lab|node)\b",
            address, maxsplit=1
        )[0].strip()
        address = re.sub(r"\b(?:street|st)\b", "st", address)
        address = re.sub(r"\b(?:road|rd)\b", "rd", address)
        address = re.sub(r"\b(?:avenue|ave)\b", "ave", address)
        address = re.sub(r"\b(?:boulevard|blvd)\b", "blvd", address)
        address = re.sub(r"\b(?:lane|ln)\b", "ln", address)
        address = re.sub(r"\s+", " ", address).strip()
        if address:
            keys.append(short("ad:", address))
    city = norm(r.get("city", ""))
    zipcode = re.sub(r"[^a-z0-9]", "", norm(r.get("zip", ""))).lstrip("0") or "0"
    gender = norm(r.get("gender", ""))
    if city and zipcode != "0":
        keys.append(short("cz:", city + "|" + zipcode))
    if gender and zipcode != "0":
        keys.append(short("gz:", gender + "|" + zipcode))
    return keys[:4]


# Character-class phonetic signatures tolerate accents, substitutions, insertions, deletions, and short name corruption.
def phonetic_name_keys(r):
    import re
    import unicodedata
    def tokens(s):
        s = unicodedata.normalize("NFKD", str(s or "")).encode("ascii", "ignore").decode().lower()
        s = s.translate(str.maketrans({"0": "o", "1": "i", "3": "e", "4": "a", "5": "s", "7": "t", "9": "g"}))
        return re.findall(r"[a-z]+", s)
    def code(word):
        groups = {
            **dict.fromkeys("bfpv", "1"),
            **dict.fromkeys("cgjkqsxz", "2"),
            **dict.fromkeys("dt", "3"),
            "l": "4",
            **dict.fromkeys("mn", "5"),
            "r": "6",
        }
        if not word:
            return ""
        out = word[0]
        previous = groups.get(word[0], "")
        for ch in word[1:]:
            current = groups.get(ch, "")
            if current and current != previous:
                out += current
            previous = current
        return (out + "000")[:4]
    values = []
    for field in ("first", "last"):
        for token in tokens(r.get(field, "")):
            if len(token) >= 2:
                signature = code(token)
                if signature and signature not in values:
                    values.append(signature)
    return ["ph:" + value for value in values[:4]]


SCHEMES = {
    "canonical_date": date_keys,
    "name_tokens": name_token_keys,
    "identifier_location": identifier_location_keys,
    "phonetic_names": phonetic_name_keys,
}
